import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    p = [0] * (n + 1)

    # Reading p_1 to p_n
    for i in range(1, n + 1):
        p[i] = int(input_data[i])

    result = []

    for start_node in range(1, n + 1):
        visited = set()
        current = start_node

        while True:
            if current in visited:
                result.append(str(current))
                break
            visited.add(current)
            current = p[current]

    print(" ".join(result))

if __name__ == "__main__":
    solve()
